def fixture_transform(src_color, rh, cw, pattern, target_colors, mismatch=None):
    # Build structurally equivalent instances with the observed box dimensions/interiors.
    specs=[(src_color,rh,cw,pattern)]+[(c,rh,cw,[]) for c in target_colors]
    if mismatch: specs.append((mismatch[0],mismatch[1],mismatch[2],[]))
    H=sum(x[1] for x in specs)+len(specs)+1
    W=max(x[2] for x in specs)+2
    g=[[0]*W for _ in range(H)]
    origins=[]; r=0
    for color,hh,ww,pat in specs:
        origins.append((color,r,1,hh,ww))
        for rr in range(hh):
            for cc in range(ww):
                if rr in (0,hh-1) or cc in (0,ww-1): g[r+rr][1+cc]=color
        for rr,cc in pat: g[r+rr][1+cc]=color
        r+=hh+1
    out=transform(g)
    # Validate each source, matching copy, and removal against the demonstrations.
    for color,r0,c0,hh,ww in origins:
        if color==src_color:
            assert all(out[r0+rr][c0+cc]==g[r0+rr][c0+cc] for rr in range(hh) for cc in range(ww))
        elif (hh,ww)==(rh,cw):
            assert all(out[r0+rr][c0+cc]==(color if (rr,cc) in pat else g[r0+rr][c0+cc]) for rr in range(1,hh-1) for cc in range(1,ww-1))
        else:
            assert all(out[r0+rr][c0+cc]==0 for rr in range(hh) for cc in range(ww))
    return True
